// ============================================================================
// LocalForm AI - Firebase module loading indirection
// ============================================================================
// Kept separate from hybrid-session.js so unit tests can stub both imports
// without the generated vendor bundle or a local config file.

// Generated by scripts/build.mjs (esbuild) from scripts/firebase-shim.mjs.
// Gitignored; run `npm run build` after `npm install` to emit it.
export async function loadFirebaseBundle() {
  return import("../vendor/firebase-ai.bundle.js");
}

// Local, gitignored Firebase web app config. See firebase-config.example.js.
export async function loadFirebaseConfig() {
  try {
    // The config file is gitignored and may not exist; keep the specifier
    // dynamic so vite/vitest import-analysis skips it, and let the runtime
    // catch handle a missing module.
    const specifier = "./firebase-config.js";
    return await import(/* @vite-ignore */ specifier);
  } catch {
    return null;
  }
}
